14	// DEVDESK-583, AC2: a proxy value that holds credentials must not come out of a
15	// tool's stderr into the progress line (footer, job detail), into the exitError
16	// text, or into the log. The tool is the test binary acting as a scanner, so
17	// what it writes on stderr is fully controlled.
18	
19	const (
20		secretPassword = "REDACTED"
21		secretUserInfo = "user:REDACTED"
22		secretProxy    = "REDACTED"
23		// The same password with a character that Go escapes in a URL userinfo.
24		escapedPassword = "REDACTED"
25		escapedProxy    = "REDACTED"
26	)
