28	// leaks lists what must not appear in any text the runner produces.
29	func leaks(text string, forbidden ...string) []string {
30		var found []string
31		for _, f := range forbidden {
32			if strings.Contains(text, f) {
33				found = append(found, f)
34			}
35		}
36		return found
37	}
