39	// captureLog collects what the package logs for the duration of one test.
40	func captureLog(t *testing.T) *bytes.Buffer {
41		t.Helper()
42		var buf bytes.Buffer
43		log.SetOutput(&buf)
44		t.Cleanup(func() { log.SetOutput(io.Discard) })
45		return &buf
46	}
