48	func TestStderrRedactsProxyCredentials(t *testing.T) {
49		cases := []struct {
50			name      string
51			proxy     string
52			stderr    string
53			forbidden []string
54			// kept is the useful part of the message, which must survive.
55			kept []string
56		}{
57			{
58				name:      "plain value",
59				proxy:     secretProxy,
60				stderr:    "proxyconnect tcp: dial " + secretProxy + " refused",
61				forbidden: []string{secretPassword, secretUserInfo, secretProxy},
62				kept:      []string{"proxyconnect tcp: dial", "proxy.corp:3128", "refused"},
63			},
64			{
65				name:      "value spread over several lines",
66				proxy:     secretProxy,
67				stderr:    "FATAL image pull failed\nvia " + secretProxy + "\ntry again later",
68				forbidden: []string{secretPassword, secretUserInfo, secretProxy},
69				kept:      []string{"FATAL image pull failed", "proxy.corp:3128", "try again later"},
70			},
71			{
72				name:      "escaped value, written as in the variable",
73				proxy:     escapedProxy,
74				stderr:    "proxyconnect: " + escapedProxy + " refused",
75				forbidden: []string{escapedPassword, "user:" + escapedPassword},
76				kept:      []string{"proxyconnect:", "proxy.corp:3128", "refused"},
77			},
78			{
79				name:      "escaped value, written decoded by the tool",
80				proxy:     escapedProxy,
81				stderr:    "proxyconnect: REDACTED refused",
82				forbidden: []string{"s3cr3t@pw", escapedPassword},
83				kept:      []string{"proxyconnect:", "refused"},
84			},
85			{
86				name:      "password alone, without the URL around it",
87				proxy:     secretProxy,
88				stderr:    "407 Proxy Authentication Required (password " + secretPassword + ")",
89				forbidden: []string{secretPassword},
90				kept:      []string{"407 Proxy Authentication Required"},
91			},
92		}
93	
94		for _, tc := range cases {
95			for _, withProgress := range []bool{true, false} {
96				name := tc.name + "/no progress callback"
97				if withProgress {
98					name = tc.name + "/progress callback"
99				}
100				t.Run(name, func(t *testing.T) {
101					useProxy(t, forwardOf(map[string]string{"HTTPS_PROXY": tc.proxy}))
102					logged := captureLog(t)
103					cmd := asScanner(t, `{"Results":[]}`, tc.stderr, 3)
104	
105					var progress []string
106					var fn func(string)
107					if withProgress {
108						fn = func(line string) { progress = append(progress, line) }
109					}
110					_, err := production.Run(context.Background(), cmd, fn)
111	
112					var exit *exitError
113					if !errors.As(err, &exit) {
114						t.Fatalf("err = %v, want an *exitError", err)
115					}
116					if exit.Code != 3 {
117						t.Errorf("exit code = %d, want 3", exit.Code)
118					}
119	
120					// (a) the error, as a field and as the text a caller shows.
121					if got := leaks(exit.Stderr, tc.forbidden...); len(got) > 0 {
122						t.Errorf("exitError.Stderr leaks %q: %q", got, exit.Stderr)
123					}
124					if got := leaks(err.Error(), tc.forbidden...); len(got) > 0 {
125						t.Errorf("the error message leaks %q: %q", got, err.Error())
126					}
127					// (b) the progress lines.
128					if withProgress {
129						if got := leaks(strings.Join(progress, "\n"), tc.forbidden...); len(got) > 0 {
130							t.Errorf("the progress lines leak %q: %q", got, progress)
131						}
132					}
133					// (c) the log.
134					if got := leaks(logged.String(), tc.forbidden...); len(got) > 0 {
135						t.Errorf("the log leaks %q: %q", got, logged.String())
136					}
137	
138					// The diagnostic is still a diagnostic: only the secret goes.
139					for _, k := range tc.kept {
140						if !strings.Contains(err.Error(), k) {
141							t.Errorf("the useful part %q was lost from %q", k, err.Error())
142						}
143						if withProgress && !strings.Contains(strings.Join(progress, "\n"), k) {
144							t.Errorf("the useful part %q was lost from the progress %q", k, progress)
145						}
146					}
147				})
148			}
149		}
150	}
