152	// Redacting must not swallow lines: one line in, one line out.
153	func TestStderrRedactionKeepsEveryProgressLine(t *testing.T) {
154		useProxy(t, forwardOf(map[string]string{"HTTPS_PROXY": secretProxy}))
155		cmd := asScanner(t, "", "first\nvia "+secretProxy+"\nthird", 0)
156	
157		var progress []string
158		if _, err := production.Run(context.Background(), cmd, func(line string) {
159			progress = append(progress, line)
160		}); err != nil {
161			t.Fatalf("Run: %v", err)
162		}
163	
164		if len(progress) != 3 || progress[0] != "first" || progress[2] != "third" {
165			t.Errorf("progress = %q, want three lines with the outer two untouched", progress)
166		}
167		if got := leaks(strings.Join(progress, "\n"), secretPassword, secretUserInfo); len(got) > 0 {
168			t.Errorf("the progress lines leak %q: %q", got, progress)
169		}
170	}
