60	// isRunLiteral reports whether e is the string literal "run" (or `run`).
61	func isRunLiteral(e ast.Expr) bool {
62		lit, ok := e.(*ast.BasicLit)
63		if !ok || lit.Kind != token.STRING {
64			return false
65		}
66		s, err := strconv.Unquote(lit.Value)
67		return err == nil && s == "run"
68	}
69	
70	// isStringSlice reports whether t is the type expression []string.
71	func isStringSlice(t ast.Expr) bool {
72		at, ok := t.(*ast.ArrayType)
73		if !ok || at.Len != nil {
74			return false
75		}
76		id, ok := at.Elt.(*ast.Ident)
77		return ok && id.Name == "string"
78	}
