82	// commandRunner is the seam every subprocess in this package passes through.
83	//
84	// The package drives trivy and gitleaks as external processes, which makes it
85	// untestable without both installed and a repository to point them at. Routing
86	// through this interface lets tests exercise the argument building, the
87	// exit-code handling and the output parsing — where the defects live — against
88	// canned output.
89	type commandRunner interface {
90		// Run executes tc and returns what it wrote to stdout. Lines written to
91		// stderr are forwarded to progressFn as they arrive, which is how Trivy
92		// reports its database download. A tool that runs and exits non-zero
93		// returns its stdout along with an *exitError.
94		Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error)
95	}
96	
97	// cliRunner is the production commandRunner: it shells out to the real tools.
98	type cliRunner struct{}
99	
100	func (cliRunner) Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error) {
101		cmd := exec.CommandContext(ctx, tc.Name, tc.Args...) //nolint:gosec // name is one of trivy/gitleaks/plumber/docker
102		cmd.Env = tc.Env                                     // nil inherits this process's environment, which is the default
103		cmd.Dir = tc.Dir                                     // empty runs in DevDesk's own working directory
104		if tc.Stdin != nil {
105			cmd.Stdin = bytes.NewReader(tc.Stdin)
106		}
107	
108		var stdout bytes.Buffer
109		cmd.Stdout = &stdout
110	
111		// Stderr is consumed two ways: streamed to progressFn while the tool runs,
112		// and kept so a failure can be reported with the tool's own diagnostic.
113		// What is kept stays raw: waitErr redacts it, on both paths. What is
114		// streamed is redacted line by line, since it leaves before the tool exits.
115		var stderr bytes.Buffer
116		fwd := proxyForward()
117		if progressFn != nil {
118			pipe, err := cmd.StderrPipe()
119			if err == nil {
120				done := make(chan struct{})
121				go func() {
122					defer close(done)
123					sc := bufio.NewScanner(pipe)
124					for sc.Scan() {
125						line := strings.TrimSpace(sc.Text())
126						if line == "" {
127							continue
128						}
129						stderr.WriteString(line)
130						stderr.WriteByte('\n')
131						progressFn(fwd.Redact(line))
132					}
133					// A read failure on the progress pipe is not a scan failure:
134					// the report comes back on stdout, and the tool's exit code
135					// says whether it succeeded. Dropping the rest of the progress
136					// is the whole consequence.
137					_ = sc.Err()
138				}()
139				if err := cmd.Start(); err != nil {
140					return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
141				}
142				<-done // drain stderr before Wait closes the pipe
143				return finish(tc.Name, cmd, &stdout, &stderr)
144			}
145		}
146	
147		cmd.Stderr = &stderr
148		if err := cmd.Start(); err != nil {
149			return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
150		}
151		return finish(tc.Name, cmd, &stdout, &stderr)
152	}
153	
154	// finish waits for the tool and only then reads what it wrote.
155	//
156	// The order is the point, and it is not a style preference: os/exec fills the
157	// output buffers from goroutines it owns, and only Wait guarantees they are
158	// done. Reading the buffer in the same expression as Wait — which is what
159	// `return stdout.Bytes(), waitErr(..., cmd.Wait(), ...)` does, since operands
160	// are evaluated before the call — snapshots it while it is still empty, and
161	// every scan comes back with no findings.
162	func finish(name string, cmd *exec.Cmd, stdout, stderr *bytes.Buffer) ([]byte, error) {
163		err := cmd.Wait()
164		return stdout.Bytes(), waitErr(name, err, stderr.String())
165	}
166	
167	// waitErr turns a non-zero exit into an *exitError carrying the code, and
168	// leaves anything else (a killed process, a broken pipe) as it is. The tool's
169	// diagnostic, from the buffer or from os/exec's ExitError.Stderr, is stripped of
170	// the proxy credentials first (DEVDESK-583).
171	func waitErr(name string, err error, stderr string) error {
172		if err == nil {
173			return nil
174		}
175		var exitErr *exec.ExitError
176		if errors.As(err, &exitErr) {
177			if stderr == "" {
178				stderr = string(exitErr.Stderr)
179			}
180			return &exitError{Code: exitErr.ExitCode(), Stderr: proxyForward().Redact(stderr)}
181		}
182		return fmt.Errorf("%s failed: %w", name, err)
183	}
