// noImplicitPull keeps `run` from fetching an image it does not have. Without
// it, launching a missing image is a pull no signature check saw (§3.82): an
// image reaches this machine through imagepull.Pull, or not at all. Measured on
// Docker and Podman: a missing image exits 125 with the engine's own message.
const noImplicitPull = "--pull=never"

// buildLaunchArgs constructs the docker run argument list for the given options.
func buildLaunchArgs(opts ContainerLaunchOptions) []string {
	args := []string{"run", noImplicitPull}
	if opts.Remove {
		args = append(args, "--rm")
	}
	if opts.Detach {
		args = append(args, "-d")
	}
	if opts.Interactive {
		args = append(args, "-i")
}

// VerifyEntrypoint checks if the given binary is available inside an image
// by running a short-lived throwaway container with /bin/sh -c "command -v <binary>".
// Returns true if the binary is found, false otherwise.
func VerifyEntrypoint(image, entrypoint string) (bool, error) {
	if err := requireEngine(); err != nil {
		return false, err
	}
	_, err := dockerCombined("run", noImplicitPull, "--rm", "--entrypoint", "/bin/sh",
		image, "-c", "command -v "+entrypoint)
	return err == nil, nil
}
// The result carries it for the caches and the callers; the **log** carries the
// detail, because the views do not print a tool's stderr any more — Rule 128's
// arrangement, which this package was not part of: a stage that failed appended
// to result.Errors and logged nothing, so the only copy of the reason was on
// screen, in a panel that replaced the findings. The footer now says to look in
// the log, and this is what makes that true.
func recordStageError(result *Result, stage string, err error) {
	log.Printf("ERROR [scan/%s] stage failed: %v", stage, err)
	result.Errors = append(result.Errors, fmt.Sprintf("%s: %v", stage, err))
}

// CountFindings aggregates findings into separate counters by category and
// severity. Vulnerabilities are counted by severity into Counts; secrets,
	Image string
	// Argv is the tool's own argv, after the image.
	Argv []string
	// Env is extra NAME=value for the child, the values of the -e NAME in Flags.
	// It never reaches argv.
	Env   []string
	Stdin []byte
}

// cmd builds `run --rm <Flags> [-e NAME]... <Image> <Argv>`. The proxy variables
// are passed by name, right before the image: their values travel in the
// child's environment, never in argv, so neither the process list nor the
// command shown in the UI carries them. Env is nil when there is neither a proxy
// to forward nor an extra variable.
func (r containerRun) cmd() toolCmd {
	fwd := proxyForward()
	args := append([]string{"run", "--rm"}, r.Flags...)
	for _, name := range fwd.Names() {
		args = append(args, "-e", name)
	}
	args = append(append(args, r.Image), r.Argv...)

	cmd := toolCmd{Name: engine.Current().Binary, Args: args, Stdin: r.Stdin}
	if !fwd.Empty() || r.Env != nil {
		cmd.Env = append(fwd.Environ(os.Environ()), r.Env...)
	}
	return cmd
}
